                Enter the date the payment was made.
              </p>
            }
          </div>
          <button type="submit" data-testid="payment-form-submit" [disabled]="saving()">Record payment</button>
          @if (saveError()) {
            <p role="alert" data-testid="payment-form-error">{{ saveError() }}</p>
