    <h1>Dashboard</h1>

    @if (loadError()) {
      <p role="alert" data-testid="dashboard-error">{{ loadError() }}</p>
    } @else if (summary(); as s) {
      <dl data-testid="dashboard-summary">
        <div>
          <dt>Clients</dt>
          <dd data-testid="dashboard-clients-count">{{ s.clients }}</dd>
        </div>
        <div>
          <dt>Projects</dt>
          <dd data-testid="dashboard-projects-count">{{ s.projects }}</dd>
        </div>
        <div>
          <dt>Outstanding</dt>
          <dd data-testid="dashboard-outstanding-total">{{ outstanding() | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</dd>
        </div>
      </dl>
    } @else {
              [attr.aria-invalid]="invalid('unitPrice')"
              [attr.aria-describedby]="invalid('unitPrice') ? 'lineitem-unitprice-error' : null"
            />
            @if (invalid('unitPrice')) {
              <p id="lineitem-unitprice-error" role="alert" data-testid="lineitem-form-unitprice-error">
                Enter a price greater than zero with at most two decimal places.
              </p>
            }
          </div>
          <button type="submit" data-testid="lineitem-form-submit" [disabled]="saving()">Add line item</button>
          @if (saveError()) {
